#include <lmcpp/lmcpp.hpp>
#include "worker.hpp"
#include <filesystem>
#include <algorithm>
#include <cmath>
#include <fstream>
#include <regex>
#include <unistd.h>
#include <cstdlib>
#include <iostream>
using namespace lmcpp; namespace fs=std::filesystem;
static std::string temp(){char p[]="/tmp/rcli-XXXXXX";int fd=mkstemp(p);if(fd<0)throw std::runtime_error("cannot create temp file");close(fd);return p;}
static Json call(const std::string& op,const Params& p){
 std::string req=temp(),out=temp(),worker=temp();{std::ofstream f(req);f<<p.dump();}{std::ofstream f(worker);f<<RCLI_WORKER_SOURCE;}
 const char* configured=getenv("RCLI_RSCRIPT");std::string exe=configured?configured:"/usr/bin/Rscript";
 int timeout_s=50;if(const char*t=getenv("RCLI_TIMEOUT_S")){try{timeout_s=std::max(1,std::min(50,std::stoi(t)));}catch(...){}}
 ChildResult c=run_child({exe,"--vanilla","--default-packages=NULL",worker,"--",op,req,out},{{"PATH","/usr/bin:/bin"},{"HOME","/tmp"},{"LC_ALL","C.UTF-8"},{"LANG","C.UTF-8"},{"R_LIBS_USER",""},{"R_PROFILE_USER","/dev/null"},{"R_ENVIRON_USER","/dev/null"},{"OMP_NUM_THREADS","1"}},std::chrono::seconds(timeout_s),1024*1024);
 unlink(req.c_str());unlink(worker.c_str()); if(c.timed_out){unlink(out.c_str());throw Error{ErrorCode::Timeout,"Rscript timed out",{{"tool_code","R_TIMEOUT"}}};}
 if(c.exit_code==127){unlink(out.c_str());throw Error{ErrorCode::ServiceUnavailable,"Rscript not found",{{"tool_code","R_NOT_FOUND"}}};}
 if(c.exit_code!=0){unlink(out.c_str());throw Error{ErrorCode::CommandFailed,"Rscript failed",{{"tool_code","TOOL_CRASH"},{"stderr",c.err}}};}
 Json res=read_result_file(out,"json");unlink(out.c_str());if(res.contains("error"))throw Error{ErrorCode::CommandFailed,res["error"].get<std::string>(),{{"tool_code","R_ERROR"},{"r_message",res["error"]}}};return res;
}
int main(int argc,char**argv){
 auto vector=[](std::string name,Type t=Type::Number,bool req=true){return Param{name,Type::Array,req,nullptr,{},"","",false,false,false,{},t};};
 Operation info{"r_info",Access::Read,"R runtime and RNG provenance","object",{}}; info.handler=[](const Params&p){return call("r_info",p);};
 Operation q{"dist_quantile",Access::Read,"Vectorized R distribution quantiles","object",{Param{"dist",Type::String,true,nullptr,{"norm","t","chisq","gamma","beta","binom","pois"}},vector("p"),Param{"lower_tail",Type::Boolean,false,true},Param{"mean",Type::Number,false,0.0},Param{"sd",Type::Number,false,1.0},Param{"df",Type::Number,false},Param{"shape",Type::Number,false},Param{"rate",Type::Number,false},Param{"a",Type::Number,false},Param{"b",Type::Number,false},Param{"size",Type::Integer,false},Param{"prob",Type::Number,false},Param{"lambda",Type::Number,false}}};q.handler=[](const Params&p){if(p["p"].size()>200000)throw Error{ErrorCode::ValidationError,"p exceeds 200000 values",{{"tool_code","INPUT_TOO_LARGE"}}};for(auto&v:p["p"])if(!v.is_number()||!std::isfinite(v.get<double>())||v.get<double>()<0||v.get<double>()>1)throw Error{ErrorCode::ValidationError,"p values must be finite and in [0,1]",{{"tool_code","BAD_PROBABILITY"}}};auto required=std::map<std::string,std::vector<std::string>>{{"t",{"df"}},{"chisq",{"df"}},{"gamma",{"shape"}},{"beta",{"a","b"}},{"binom",{"size","prob"}},{"pois",{"lambda"}}};for(auto&k:required[p["dist"]])if(!p.contains(k))throw Error{ErrorCode::ValidationError,"missing distribution parameter: "+k,{{"tool_code","MISSING_DISTRIBUTION_PARAMETER"}}};if((p.contains("sd")&&p["sd"]<=0)||(p.contains("df")&&p["df"]<=0)||(p.contains("shape")&&p["shape"]<=0)||(p.contains("rate")&&p["rate"]<=0)||(p.contains("a")&&p["a"]<=0)||(p.contains("b")&&p["b"]<=0)||(p.contains("lambda")&&p["lambda"]<0)||(p.contains("prob")&&(p["prob"]<0||p["prob"]>1)))throw Error{ErrorCode::ValidationError,"distribution parameters are outside their valid domain",{{"tool_code","BAD_DISTRIBUTION_PARAMETER"}}};return call("dist_quantile",p);};
 Operation rng{"rng_draw",Access::Read,"Seeded R normal or uniform draws","object",{Param{"dist",Type::String,true,nullptr,{"norm","unif"}},Param{"n",Type::Integer,true},Param{"seed",Type::Integer,true},Param{"mean",Type::Number,false,0.0},Param{"sd",Type::Number,false,1.0},Param{"min",Type::Number,false,0.0},Param{"max",Type::Number,false,1.0}}};rng.handler=[](const Params&p){if(p["n"]<0||p["n"]>200000)throw Error{ErrorCode::ValidationError,"n must be between 0 and 200000",{{"tool_code","BAD_SIZE"}}};return call("rng_draw",p);};
 Operation fit{"fit_lm",Access::Read,"Fit an R linear model from inline data or CSV","object",{Param{"formula",Type::String,true},Param{"data",Type::Object,false},Param{"file",Type::String,false},Param{"residuals",Type::Boolean,false,false},Param{"na_action",Type::String,false,"omit",{"omit","exclude"}}}};fit.handler=[](const Params&p){static const std::regex f("^[A-Za-z.][A-Za-z0-9._]* *~ *[A-Za-z.][A-Za-z0-9._]*( *\\+ *[A-Za-z.][A-Za-z0-9._]*)*$");if(!std::regex_match(p["formula"].get<std::string>(),f))throw Error{ErrorCode::ValidationError,"formula must contain column names and + only",{{"tool_code","BAD_FORMULA"}}};if(p.contains("file")==p.contains("data"))throw Error{ErrorCode::ValidationError,"provide exactly one of file or data",{{"tool_code","DATA_SOURCE_REQUIRED"}}};if(p.contains("data")){size_t n=0;for(auto it=p["data"].begin();it!=p["data"].end();++it){if(!it.value().is_array())throw Error{ErrorCode::ValidationError,"data columns must be arrays",{{"tool_code","BAD_DATA"}}};if(n&&it.value().size()!=n)throw Error{ErrorCode::ValidationError,"data columns must have equal lengths",{{"tool_code","BAD_DATA"}}};n=it.value().size();if(n>200000)throw Error{ErrorCode::ValidationError,"data exceeds 200000 rows",{{"tool_code","INPUT_TOO_LARGE"}}};for(const auto& v:it.value())if(!v.is_null()&&!v.is_number())throw Error{ErrorCode::ValidationError,"data values must be numeric or null",{{"tool_code","BAD_DATA"}}};}}if(p.contains("file")){fs::path cwd=fs::weakly_canonical(fs::current_path()), path=fs::weakly_canonical(p["file"].get<std::string>());auto rel=path.lexically_relative(cwd);if(rel.empty()||*rel.begin()==".."||!fs::is_regular_file(path))throw Error{ErrorCode::ValidationError,"CSV file must be a regular file under current directory",{{"tool_code","PATH_OUTSIDE_CWD"}}};}return call("fit_lm",p);};
 CliSpec spec{"rcli","0.1.0",{info,q,rng,fit}};return run_cli(spec,argc,argv);
}
